/* ===================================
   FRAPPE/ERPNEXT PRINT SETTINGS - A4 LANDSCAPE FULL PAGE
   =================================== */
@media print {
  @page {
    size: A4 landscape;
    margin: 0mm;
  }

  body {
    margin: 0;
    padding: 0 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    background: transparent !important;
    font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
    font-size: 10px !important;
    color: #000 !important;
    box-sizing: border-box;
  }
}

@media screen {
  .print-format {
    margin: 0 !important;
    padding: 0 !important;
    max-width: none !important;
    min-height: auto !important;
  }
}

/* ===================================
   CONTAINER SETUP - A4 FULL PAGE
   Full A4 Landscape: 297mm x 210mm
   =================================== */
.certificate-container {
  position: relative;
  width: 297mm;  /* Full A4 landscape width */
  height: 210mm; /* Full A4 landscape height */
  background-repeat: no-repeat !important;
  background-size: cover !important;
  background-position: center !important;
  color: #000 !important;
  page-break-after: avoid;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-size: 10px !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.certificate-section {
  position: absolute;
  width: 148.5mm; /* Half of 297mm */
  height: 210mm;
  box-sizing: border-box;
  font-size: 10px !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  color: #000 !important;
  background: transparent;
}

.left-section {
  top: 0;
  left: 0;
}

.right-section {
  top: 0;
  left: 148.5mm; /* Start after left section */
}

/* ===================================
   COMMON TEXT STYLES - 100% BLACK FONT
   =================================== */
.certificate-no,
.account-no,
.holder-name,
.holder-address,
.share-count,
.share-from,
.share-to,
.total-value,
.issue-date,
.duplicate-text {
  position: absolute;
  font-weight: bold;
  text-transform: uppercase;
  margin: 0;
  padding: 0;
  font-size: 10px !important;
  line-height: 1.2;
  color: #000 !important;
  box-sizing: border-box;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  background: transparent;
  z-index: 10;
}

