/* ===================================
   FRAPPE/ERPNEXT SPECIFIC OVERRIDES - 100% BLACK
   =================================== */
.print-format {
  margin: 0mm !important;
  padding: 0 !important;
  max-width: none !important;
  min-height: auto !important;
  background: white !important;
  font-size: 10px !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  color: #000 !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.print-format * {
  color: #000 !important;
  font-size: 10px !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

/* Background image support for wkhtmltopdf */
.print-format .certificate-container {
  background-repeat: no-repeat !important;
  background-size: cover !important;
  background-position: center !important;
  color: #000 !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

/* Ensure no interference from Bootstrap */
.print-format .container,
.print-format .container-fluid {
  padding: 0 !important;
  margin: 0 !important;
  font-size: 10px !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

/* Disable any default table styling with black text */
.print-format table {
  border: none !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 10px !important;
  color: #000 !important;
}

.print-format table td,
.print-format table th {
  font-size: 10px !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

/* ===================================
   RESPONSIVE ADJUSTMENTS
   =================================== */
@media screen {
  .certificate-container {
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
    margin: 20px auto;
    background: white;
    font-size: 10px !important;
    color: #000 !important;
    font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  }
}

/* ===================================
   FRAPPE PDF SPECIFIC STYLES - BLACK TEXT
   =================================== */
.print-format {
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  font-size: 10px !important;
  color: #000 !important;
  margin: 0mm !important;
}

/* Prevent page breaks within certificate sections */
.certificate-section {
  page-break-inside: avoid;
}

/* Ensure proper text rendering in PDF with black text */
.certificate-no,
.account-no,
.holder-name,
.holder-address,
.share-count,
.share-from,
.share-to,
.total-value,
.issue-date,
.duplicate-text {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-size: 10px !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
  z-index: 10;
}

/* Additional font size enforcement for nested elements with black text */
.certificate-container div,
.certificate-container span,
.certificate-container p {
  font-size: 10px !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

/* Force font size for any jinja rendered content with black text */
.print-format .ql-editor {
  font-size: 10px !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

.print-format .ql-editor p {
  font-size: 10px !important;
  margin: 0 !important;
  padding: 0 !important;
  color: #000 !important;
  font-family: "Courier New", Courier, "Lucida Console", Monaco, monospace !important;
}

/* ===================================
   WKHTMLTOPDF BACKGROUND IMAGE SUPPORT - FULL PAGE
   =================================== */
@media print {
  .certificate-container {
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-position: center !important;
    color: #000 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  body {
    color: #000 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }
}
